        } else {
            let range = (i64::from(a.maximum) - i64::from(a.minimum)).max(1);
            d * 1000 > TAP_MAX_TRAVEL_PERMILLE * range
        }
    };
    too_far(sx, ex) || too_far(sy, ey)
}

