    }

    #[test]
    fn shortcuts_are_ignored() {
        for (k, m) in [
            ("c", CTRL),
            ("s", CTRL),
            ("Tab", &[Mod::Alt][..]),
            ("e", &[Mod::Super][..]),
            ("Escape", NONE),
