        l.push(t + 100, "notes", EventKind::Click { button: "left".into(), window: "n".into() });
        let t = l.typ(t + 200, "notes", "n", "c");
        l.key(t, "notes", "n", "v", &[Mod::Ctrl]);
        l.push(t, "notes", EventKind::Paste { text: Some(" pasted".into()), window: "n".into() });
        // In a terminal, plain Ctrl+V does not paste.
        l.key(t + 100, "org.kde.konsole", "~", "v", &[Mod::Ctrl]);
        l.push(t + 100, "org.kde.konsole", EventKind::Paste { text: Some("nope".into()), window: "~".into() });
        l.key(t + 200, "org.kde.konsole", "~", "V", &[Mod::Ctrl, Mod::Shift]);
        l.push(t + 200, "org.kde.konsole", EventKind::Paste { text: Some("yes".into()), window: "~".into() });
        let mut ing = l.ingester("b.db");
