        // it started from, but whitespace-only changes are still edits; it
        // is kept only because the document is non-empty... it is "x".
        let s = sessions(ing.connection());
        assert_eq!(s.iter().filter(|s| s.0 == "dolphin").count(), 0);
        assert_eq!(s[0].4, "x");
