    fn stop_and_restart_close_sessions() {
        let mut l = Log::new();
        let t = l.typ(T0, "notes", "n", "one");
        l.sys(t, SystemState::Stop);
        l.sys(t + 100, SystemState::Start);
        let t = l.typ(t + 200, "notes", "n", " two");
